/// <reference types="../../../types/react-table-config" />

import React from 'react';
import { isElement } from 'react-is';
import type { Cell, TableDispatch } from 'react-table';

import { CopyItem } from './CopyItem.js';
import { TableUserActions } from './TableUserActions.js';
import { useActionsMenuAlignment } from './useActionMenuAlignment.js';
import { TableUserActionsContext } from './useTableUserActionsContext.js';
import { Menu } from '../../../../navigation/menu/Menu.js';

export type CellActionsMenuProps = {
  trigger: React.ReactNode;
  cell: Cell;
  tableUserActions: React.ReactElement;
  onClose: () => void;
  dispatch: TableDispatch;
  cellButtonRef: React.RefObject<HTMLButtonElement>;
  tableContainerRef: React.RefObject<HTMLDivElement>;
};

/**
 * Separates a `TableUserActions` object containing cell actions into
 * default action items and custom action items.
 *
 * @param tableUserActions - An instance of `TableUserActions`.
 */
function separateCellActions(tableUserActions: React.ReactElement) {
  const actions = {
    defaultActions: [] as React.ReactNode[],
    customActions: [] as React.ReactNode[],
  };

  if (
    !isElement(tableUserActions) ||
    tableUserActions.type !== TableUserActions
  ) {
    return actions;
  }

  React.Children.forEach(tableUserActions.props.children, (child) => {
    if (!isElement(child)) {
      return;
    }

    switch (child.type) {
      case CopyItem:
        actions.defaultActions.push(child);
        break;
      default:
        actions.customActions.push(child);
        break;
    }
  });

  return actions;
}

export const CellActionsMenu = ({
  trigger,
  cell,
  tableUserActions,
  onClose,
  dispatch,
  cellButtonRef,
  tableContainerRef,
}: CellActionsMenuProps) => {
  const { column, row } = cell;
  const wrappedUserActions =
    isElement(tableUserActions) && tableUserActions.type !== TableUserActions;
  const { defaultActions, customActions } =
    separateCellActions(tableUserActions);

  const alignment = useActionsMenuAlignment(
    tableContainerRef,
    cellButtonRef,
    column,
  );

  return defaultActions.length > 0 || customActions.length > 0 ? (
    <TableUserActionsContext.Provider value={{ cell, row, column, dispatch }}>
      <Menu open={true} onOpenChange={(isOpen) => !isOpen && onClose()}>
        <Menu.Trigger>{trigger}</Menu.Trigger>
        <Menu.Content alignment={alignment}>
          {defaultActions.length > 0 ? (
            <Menu.Group>{defaultActions}</Menu.Group>
          ) : null}
          {wrappedUserActions ? tableUserActions : customActions}
        </Menu.Content>
      </Menu>
    </TableUserActionsContext.Provider>
  ) : null;
};

(
  CellActionsMenu as typeof CellActionsMenu & { displayName: string }
).displayName = 'CellActionsMenu';
